import pandas as pd
import numpy as np
from scipy import stats

# Load all available experiments
dfs = {}
for exp_id in [1, 5, 6, 7, 8, 9, 10, 11]:
    try:
        path = eval(f"experiment_{exp_id}_csv")
        df = pd.read_csv(path)
        df['exp_id'] = exp_id
        dfs[exp_id] = df
        print(f"Exp {exp_id}: n={len(df)}, cols={list(df.columns)}")
        print(f"  CropYield mean={df['CropYield'].mean():.3f}, SD={df['CropYield'].std():.3f}")
        if 'SoilAcidifier' in df.columns:
            print(f"  SoilAcidifier={df['SoilAcidifier'].mean():.1f}")
        if 'LeafGreenness' in df.columns:
            print(f"  LeafGreenness mean={df['LeafGreenness'].mean():.3f}")
    except Exception as e:
        print(f"Exp {exp_id}: ERROR {e}")
